/**
 * Secondo passo di String it su Unity con XUnity: i testi che XUnity ha
 * catturato giocando si ritraducono TUTTI con la catena AI dell'app (memoria,
 * glossario, profilo), e si scrivono in un file di traduzione che XUnity
 * preferisce al suo `_AutoGeneratedTranslations.txt` (quello di Google).
 *
 * Il lavoro sui file lo fa Rust (`read_captured_translations`,
 * `write_translation_file` in unity_patcher.rs); qui ci sono l'ordine dei
 * passi e le regole su cosa conta come traduzione. Le dipendenze sono
 * iniettate, così la regola si prova senza Tauri né AI.
 */
import { invoke } from '@/lib/tauri-api';

export interface XUnityEntry {
  original: string;
  translated: string;
  line_number: number;
}

export type XUnityAiOutcome =
  | { status: 'done'; changed: number; failed: number; total: number; path: string }
  /** XUnity non ha ancora catturato niente: serve giocare prima. */
  | { status: 'no-captures' }
  /** Nessun testo tradotto, o scrittura fallita: nel gioco non è cambiato nulla. */
  | { status: 'failed'; reason: string };

export interface XUnityAiDeps {
  readCaptured: (gamePath: string, lang: string) => Promise<XUnityEntry[]>;
  write: (gamePath: string, lang: string, gameName: string, entries: XUnityEntry[]) => Promise<string>;
}

const tauriDeps: XUnityAiDeps = {
  readCaptured: (gamePath, lang) => invoke<XUnityEntry[]>('read_captured_translations', { gamePath, lang }),
  write: (gamePath, lang, gameName, entries) =>
    invoke<string>('write_translation_file', { gamePath, lang, gameName, entries }),
};

export interface XUnityAiOptions {
  gamePath: string;
  /** La lingua come la usa XUnity (`Translation/{lang}/Text`). */
  lang: string;
  gameName: string;
  /** Restituisce un array lungo quanto l'ingresso, con `null` dove la traduzione non è arrivata. */
  translate: (texts: string[]) => Promise<(string | null)[]>;
  deps?: XUnityAiDeps;
}

export async function runXUnityAiTranslation(options: XUnityAiOptions): Promise<XUnityAiOutcome> {
  const { gamePath, lang, gameName, translate, deps = tauriDeps } = options;

  let captured: XUnityEntry[];
  try {
    captured = await deps.readCaptured(gamePath, lang);
  } catch {
    // Il comando fallisce quando il file non c'è ancora: il gioco non è stato avviato.
    return { status: 'no-captures' };
  }

  // Si ritraduce anche ciò che Google ha già tradotto: è il motivo del passo.
  const texts = Array.from(new Set(captured.map(e => e.original).filter(t => t.trim() !== '')));
  if (texts.length === 0) return { status: 'no-captures' };

  let results: (string | null)[];
  try {
    results = await translate(texts);
  } catch (e: unknown) {
    return { status: 'failed', reason: String(e) };
  }

  // Una traduzione uguale all'originale non è una traduzione: scriverla
  // coprirebbe quella di Google con l'inglese.
  const entries: XUnityEntry[] = [];
  texts.forEach((original, i) => {
    const translated = results[i]?.trim();
    if (translated && translated !== original.trim()) {
      entries.push({ original, translated, line_number: 0 });
    }
  });
  if (entries.length === 0) {
    return { status: 'failed', reason: `0 testi tradotti su ${texts.length}` };
  }

  try {
    const path = await deps.write(gamePath, lang, gameName, entries);
    return { status: 'done', changed: entries.length, failed: texts.length - entries.length, total: texts.length, path };
  } catch (e: unknown) {
    return { status: 'failed', reason: String(e) };
  }
}
